    for (const q of fxLive) if (q.vec && q.vis) { const V = VEC[q.vid], F = q.fx, u = V.loop ? (F.t % F.dur) / F.dur : Math.min(1, F.t / F.dur); try { ex.save(); ex.translate(F.options.x * k, F.options.y * k); ex.scale(k * VS, k * VS); if (q.ang) ex.rotate(q.ang); if (q.flip) ex.scale(-1, 1); ex.lineJoin = 'round'; ex.lineCap = 'round'; if (V.loop) ex.globalAlpha = Math.min(1, F.t / .15) * (F.stopT != null ? Math.max(0, 1 - (F.t - F.stopT) / .25) : 1); V.draw(ex, u, q, F.t); } catch (err) { q.broken = true; console.error('VFX', q.vid, err); } finally { ex.restore(); } }
    for (const q of fxLive) if (q.vec && q.vis && q.fx.ltd) { /* 빛 번짐: 벡터도 은은하게 */ const V = VEC[q.vid]; if (!V.glow) continue; lx.save(); lx.translate(q.fx.options.x * k, q.fx.options.y * k); lx.scale(k, k); lx.filter = `blur(${Math.round(k * 3)}px)`; V.glow(lx, Math.min(1, q.fx.t / q.fx.dur), q); lx.restore(); }
