  // ───── 그리기 도구 (단위 = 버퍼 px, 원점 = 이펙트 자리) ─────
  const ease = u => 1 - (1 - u) * (1 - u), back = u => { const s = 1.7; u -= 1; return u * u * ((s + 1) * u + s) + 1; };
  function fillOL(ctx, path, col, w = LW) { ctx.lineWidth = w * 2; ctx.strokeStyle = OL; ctx.stroke(path); ctx.fillStyle = col; ctx.fill(path); }
  function lineOL(ctx, pts, col, w) { const p = new Path2D(); pts.forEach(([x, y], i) => i ? p.lineTo(x, y) : p.moveTo(x, y)); ctx.strokeStyle = OL; ctx.lineWidth = w + LW * 2; ctx.stroke(p); ctx.strokeStyle = col; ctx.lineWidth = w; ctx.stroke(p); }
  function star(n, R, r, rot = 0) { const p = new Path2D(); for (let i = 0; i < n * 2; i++) { const a = rot + i * Math.PI / n, d = i % 2 ? r : R; i ? p.lineTo(Math.cos(a) * d, Math.sin(a) * d) : p.moveTo(Math.cos(a) * d, Math.sin(a) * d); } p.closePath(); return p; }
  function circ(x, y, r) { const p = new Path2D(); p.arc(x, y, Math.max(.1, r), 0, 6.283); return p; }
