  function flame(c, x, b, w, h, wob = 0, o1 = '#ff7a2a', o2 = '#ffe27a') { const p = new Path2D(); p.moveTo(x - w, b); p.quadraticCurveTo(x - w, b - h * .6, x + wob, b - h); p.quadraticCurveTo(x + w, b - h * .6, x + w, b); p.closePath(); fillOL(c, p, o1); const p2 = new Path2D(); p2.moveTo(x - w * .5, b); p2.quadraticCurveTo(x - w * .5, b - h * .35, x + wob * .5, b - h * .55); p2.quadraticCurveTo(x + w * .5, b - h * .35, x + w * .5, b); p2.closePath(); c.fillStyle = o2; c.fill(p2); }
  // 폭발: 섬광 → 불덩이 → 연기, 파편이 튄다. s = 크기
  const FIRE_P = ['#fff6c0', '#ffb43a', '#ff7a2a', '#c8502a', '#8a5040', '#6a6070', '#8a8494', '#ffe08a'];
