    'nature/thorns': { dur: 1.1, draw(c, u, q) { for (let i = 0; i < 7; i++) { const a = q.seed + i * .9, x = Math.cos(a) * (6 + i % 3 * 4), y = Math.sin(a) * 4, v = Math.max(0, Math.min(1, (u - i * .03) * 5)) * fin(u), h = (10 + i % 3 * 5) * v; if (h < .5) continue; const p = new Path2D(); p.moveTo(x - 2, y); p.quadraticCurveTo(x - 3, y - h * .6, x + Math.sin(a) * 4, y - h); p.quadraticCurveTo(x + 1, y - h * .5, x + 2, y); p.closePath(); fillOL(c, p, '#6a8a3a'); spike(c, x - 1.6, y - h * .5, .9, 3, '#c8d890'); } } },
    'nature/spore-burst': { dur: 1.1, draw(c, u, q, t) { cloud(c, u, q.seed, ['#c8d460', '#a8b848', '#e0e890'], 8, 1, 6); withA(c, fin(u), () => { for (let i = 0; i < 10; i++) { const a = t * 5 + i * .628 + q.seed, r = 6 + (i * 7 % 14) * ease(u); fillOL(c, circ(Math.cos(a) * r, -12 + Math.sin(a * 1.3) * r * .5, .7), '#2a2a1a', .5); } }); } },
    'nature/root-snare': { dur: 1.2, draw(c, u, q) { for (let i = 0; i < 5; i++) { const a = q.seed + i * 1.257, x0 = Math.cos(a) * 12, y0 = Math.sin(a) * 4, v = Math.max(0, Math.min(1, (u - i * .04) * 3.5)) * fin(u); if (v < .02) continue; const pts = []; for (let j = 0; j <= 8; j++) { const s = j / 8 * v; pts.push([x0 * (1 - s * .8) + Math.sin(s * 6 + i) * 3, y0 * (1 - s) - s * 18]); } lineOL(c, pts, i % 2 ? '#8a5a3a' : '#6a4a2a', 2.2 * (1 - v * .3)); } } },
    'nature/quake': { dur: 1, shake: .5, draw(c, u, q) { withA(c, fin(u), () => { for (let i = 0; i < 6; i++) { const a = q.seed + i * 1.047, L = ease(Math.min(1, u * 2.5)) * 24; lineOL(c, zig(0, 0, Math.cos(a) * L, Math.sin(a) * L * .4, 4, 2, q.seed + i), '#2a1a14', 1.2); } for (let i = 0; i < 6; i++) { const a = q.seed * 2 + i * 1.047, v = Math.min(1, u * 1.5), x = Math.cos(a) * (6 + v * 14), y = Math.sin(a) * (2 + v * 5) - Math.sin(v * 3.14) * 14; c.save(); c.translate(x, y); fillOL(c, star(3, 2.6, 1.6, a), i % 2 ? '#8a7a6a' : '#6a5a4a', .8); c.restore(); } }); } },
