    'nature/leaf-storm': { dur: 1.2, draw(c, u, q, t) { withA(c, fadeIn(u) * fin(u), () => { for (let i = 0; i < 10; i++) { const a = t * 4 + i * .628, r = 10 + (i % 3) * 4, y = -6 - (i % 5) * 6; leaf(c, Math.cos(a) * r, y + Math.sin(a) * r * .35, 2.6, a * 2, i % 2 ? '#7ec04a' : '#a8d860'); } }); } },
    'nature/healing-bloom': { dur: 1.2, glow: glowC('rgba(150,255,150,A)', 16, -4), draw(c, u, q) { const o = u < .4 ? ease(u / .4) : 1; withA(c, fin(u), () => { for (let i = 0; i < 6; i++) { const a = i * 1.047 + u * .5; c.save(); c.translate(Math.cos(a) * 4 * o, Math.sin(a) * 1.6 * o); c.rotate(a); const p = new Path2D(); p.ellipse(3.4 * o, 0, 4 * o + .1, 2 * o + .1, 0, 0, 6.283); fillOL(c, p, i % 2 ? '#ff9ac8' : '#ffb8d8', .8); c.restore(); } fillOL(c, circ(0, 0, 2 * o + .1), '#ffe27a', .8); for (let i = 0; i < 3; i++) { const v = (u * 1.5 + i / 3) % 1, s2 = 1, x = (i - 1) * 7, y = -6 - v * 20, p = new Path2D(); p.rect(x - s2 * .8, y - s2 * 2.6, s2 * 1.6, s2 * 5.2); p.rect(x - s2 * 2.6, y - s2 * .8, s2 * 5.2, s2 * 1.6); withA(c, Math.sin(v * 3.14), () => fillOL(c, p, '#7ef07e', .8)); } }); } },
