    'shadow/void-orb': { dur: 1.2, glow: glowC('rgba(140,60,220,A)', 20, -18), draw(c, u, q, t) { const s = u < .3 ? back(u / .3) : u > .8 ? (1 - u) / .2 : 1; for (let i = 0; i < 8; i++) { const v = (t * 1.5 + i / 8) % 1, a = i * .785 + t * 2, r = 22 * (1 - v); withA(c, v, () => fillOL(c, circ(Math.cos(a) * r, -18 + Math.sin(a) * r * .6, 1.2), '#c88aff', .6)); } const p = circ(0, -18, 9 * s + .1); c.fillStyle = '#120818'; c.fill(p); c.strokeStyle = '#a050f0'; c.lineWidth = 2; c.stroke(p); c.strokeStyle = OL; c.lineWidth = .8; c.stroke(circ(0, -18, 9 * s + 1.5)); } },
    'shadow/soul-drain': { dur: 1.1, draw(c, u, q, t) { for (let i = 0; i < 4; i++) { const v = (u * 1.3 - i * .1); if (v <= 0 || v >= 1) continue; const x = (i - 1.5) * 5 + Math.sin(t * 6 + i) * 3, y = -10 - v * 34, p = new Path2D(); p.moveTo(x, y - 4); p.quadraticCurveTo(x + 3.4, y, x + Math.sin(t * 8 + i) * 2, y + 6); p.quadraticCurveTo(x - 3.4, y, x, y - 4); withA(c, Math.sin(v * 3.14), () => { fillOL(c, p, '#9ae8c8', .8); c.fillStyle = OL; c.fill(circ(x - 1, y - 1, .5)); c.fill(circ(x + 1, y - 1, .5)); }); } } },
