    'shadow/grasping-hands': { dur: 1.3, draw(c, u, q, t) { for (let i = 0; i < 4; i++) { const a = q.seed + i * 1.571, x = Math.cos(a) * 10, y = Math.sin(a) * 3.6, v = Math.max(0, Math.min(1, (u - i * .05) * 3)) * fin(u), h = 16 * v; if (h < .5) continue; c.save(); c.translate(x, y); c.rotate(Math.sin(t * 4 + i) * .2); const arm = new Path2D(); arm.rect(-1.8, -h, 3.6, h); fillOL(c, arm, '#2a1a34'); const pm = circ(0, -h - 2, 3.2); fillOL(c, pm, '#3a2448'); for (let j = 0; j < 4; j++) { const fa = -2.4 + j * .55; lineOL(c, [[Math.cos(fa) * 2.4, -h - 2 + Math.sin(fa) * 2.4], [Math.cos(fa) * 5.6, -h - 2 + Math.sin(fa) * 5.6]], '#3a2448', 1.3); } c.restore(); } } },
