    'arcane/blink-out': { dur: .6, glow: glowC('rgba(170,120,255,A)', 14, -16), draw(c, u, q) { const w = u < .5 ? 10 * (1 - u * 2) + .5 : .5, h = u < .5 ? 30 : 30 * (1 - (u - .5) * 2); withA(c, fin(u), () => { const p = new Path2D(); p.ellipse(0, -16, w, h / 2 + .1, 0, 0, 6.283); fillOL(c, p, '#c8a8ff'); }); for (let i = 0; i < 6; i++) { const a = q.seed + i * 1.047, r = 16 * (1 - ease(u)); withA(c, Math.sin(u * 3.14), () => sparkle(c, Math.cos(a) * r, -16 + Math.sin(a) * r, 2, '#ffffff', u * 4)); } } },
