    'spawn/soul-rise': { dur: 1.6, draw(c, u, q, t) { const y = -14 - ease(u) * 34, x = Math.sin(t * 3) * 3; withA(c, fadeIn(u, .2) * (1 - u), () => { const p = new Path2D(); p.moveTo(x, y - 7); p.bezierCurveTo(x + 6, y - 7, x + 6, y + 2, x + 3, y + 7); p.quadraticCurveTo(x + 1, y + 4, x, y + 8); p.quadraticCurveTo(x - 1, y + 4, x - 3, y + 7); p.bezierCurveTo(x - 6, y + 2, x - 6, y - 7, x, y - 7); fillOL(c, p, '#e8f4ff'); c.fillStyle = OL; c.fill(circ(x - 1.8, y - 2, .9)); c.fill(circ(x + 1.8, y - 2, .9)); }); } },
